"""reach_table.py -- 11/11 R5 step 1 (c) (Lin 11/11 "(c) look the table up, no extra IK at run time: let's try"; task_R5_from_supervisor.md).

Pure lookup in scenes/area.json (computed offline, note 81, by reference/smart_picking_v1/grasp_v1/demo/env_area.py cell_ok_tilt).
No IK, no Kit, no other lab module, no v1 kin import. Nothing here moves the arm: the caller (step 2, behind a switch) decides.

area.json, as read here:
  cells (663)        the layout cells = 603 ordinary (straight down, not in note81.rows) + 60 note 81 cells
  all_cells (675)    the 663 + the 12 judged "beyond the 1.20 m limit" (ok False)
  note81.rows (72)   per judged cell: how = "straight_lowered_transfer" (14, no height recorded) / "tilt" (46, per closing direction
                     0, 30 .. 150 deg and per class: tilt_deg (signed), tilt_axis about_close / about_across, z_transfer) /
                     "beyond the 1.20 m limit" (12)
  2 cm grid.

reach_mode(xy, close_yaw_deg, cls, table) -> dict(mode=..., reason=..., cells=[...], ...), mode one of
  straight     the ordinary grasp
  lowered      the ordinary grasp, but v1 needed a lower transfer height there (z_transfer None: area.json does not record it)
  tilt         tilt_deg (signed), tilt_axis, z_transfer, dir_deg (the table direction used), tilt_max_deg (of the cell)
  unknown      no answer from the table (outside the 663 cells, or next to one of the 12 beyond-limit cells, or a class / direction
               the table has no entry for); never guessed as straight. table_says = "unreachable" when the table judged it so.
Rules (plan_reach_c_a.md step 1, supervisor's change 2):
  - the nearest grid cell; every cell within NEAR_BAND_M of the nearest distance also counts (a point on a cell border sees both);
  - the nearest cell farther than MAX_NEAR_M (1.5 cm) -> unknown (the grid's own points are at most 1.42 cm from a centre);
  - several cells -> the strictest: unknown > tilt (larger |tilt|) > lowered > straight;
  - close_yaw_deg = the finger closing axis in world XY (grasp/planner.py yaw_deg; 180-deg symmetric) -> the nearest table direction;
    exactly between two (e.g. 15 deg) -> both, the stricter.
"""
import json, math, os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
AREA = os.path.join(ROOT, "scenes", "area.json")
GRID_M = 0.02
MAX_NEAR_M = 0.015
NEAR_BAND_M = 0.005
RANK = {"straight": 0, "lowered": 1, "tilt": 2, "unknown": 3}


def load_table(path=AREA):
    """area.json -> {(x_mm, y_mm): entry}; entry = dict(xy, how, row). Keys in whole mm (the cells are on a 1 mm-exact grid)."""
    a = json.load(open(path))
    rows = {_key(r["xy"]): r for r in a["note81"]["rows"]}
    cells = {_key(c) for c in a["cells"]}
    t = {}
    for c in a["all_cells"]:
        k = _key(c); r = rows.get(k)
        if k in cells and r is None:
            how = "straight"
        elif k in cells and r["ok"] and r["how"] == "straight_lowered_transfer":
            how = "lowered"
        elif k in cells and r["ok"] and r["how"] == "tilt":
            how = "tilt"
        else:
            how = "unknown"
        t[k] = dict(xy=[float(c[0]), float(c[1])], how=how, row=r, in_cells=k in cells)
    return dict(cells=t, source=os.path.relpath(path, ROOT), n_cells=len(cells), n_all=len(t), env=a.get("env"))


def _key(xy):
    return (int(round(float(xy[0]) * 1000)), int(round(float(xy[1]) * 1000)))


def near_cells(xy, table):
    """The nearest cell and every cell within NEAR_BAND_M of that distance: [(dist_m, entry)], nearest first."""
    d = sorted((math.hypot(e["xy"][0] - xy[0], e["xy"][1] - xy[1]), k) for k, e in table["cells"].items())
    if not d:
        return []
    return [(dk, table["cells"][k]) for dk, k in d if dk <= d[0][0] + NEAR_BAND_M]


def table_dirs(close_yaw_deg, dirs=(0, 30, 60, 90, 120, 150)):
    """Table directions nearest to a closing axis (mod 180); two when exactly between."""
    y = float(close_yaw_deg) % 180.0
    gap = lambda d: abs(((y - d + 90.0) % 180.0) - 90.0)
    g0 = min(gap(d) for d in dirs)
    return [d for d in dirs if gap(d) <= g0 + 1e-6]


def _one(entry, close_yaw_deg, cls):
    """The answer of one cell."""
    how, r = entry["how"], entry["row"]
    out = dict(cell=entry["xy"])
    if how in ("straight", "lowered"):
        return dict(out, mode=how, reason=("ordinary cell" if how == "straight" else "note 81: straight with a lowered transfer height (height not recorded)"),
                    z_transfer=None)
    if how == "unknown":
        says = "unreachable" if (r is not None and not r.get("ok")) else None
        return dict(out, mode="unknown", reason=("not one of the layout cells (area.json cells)" +(f" (note 81: {r['how']})" if r else "")), table_says=says)
    best = None
    for d in table_dirs(close_yaw_deg, [x["dir_deg"] for x in r["dirs"]]):
        dd = next(x for x in r["dirs"] if x["dir_deg"] == d)
        b = (dd.get("bins") or {}).get(cls)
        if b is None:
            return dict(out, mode="unknown", reason=f"note 81 tilt cell has no entry for class {cls!r} at dir {d}", table_says=None)
        cand = dict(out, mode="tilt", reason=f"note 81 tilt cell, dir {d}", dir_deg=d, tilt_deg=b["tilt_deg"], tilt_axis=b["tilt_axis"],
                    z_transfer=round(float(b["z_transfer"]), 4), tilt_max_deg=r.get("tilt_max_deg"))
        if best is None or abs(cand["tilt_deg"]) > abs(best["tilt_deg"]):
            best = cand
    return best


def reach_mode(xy, close_yaw_deg, cls, table):
    """See the module docstring. xy = the grasp point (world, m); close_yaw_deg = the planned closing axis; cls = the class name."""
    near = near_cells(xy, table)
    if not near:
        return dict(mode="unknown", reason="empty table", cells=[], table_says=None)
    if near[0][0] > MAX_NEAR_M:
        return dict(mode="unknown", reason=f"outside the table: nearest cell {near[0][0] * 1000:.1f} mm away (> {MAX_NEAR_M * 1000:.0f} mm)",
                    cells=[dict(cell=near[0][1]["xy"], dist_mm=round(near[0][0] * 1000, 1))], table_says=None)
    ans = [(dk, _one(e, close_yaw_deg, cls)) for dk, e in near]
    worst = max(ans, key=lambda a_: (RANK[a_[1]["mode"]], abs(a_[1].get("tilt_deg") or 0)))[1]
    res = dict(worst, cells=[dict(cell=a_["cell"], mode=a_["mode"], dist_mm=round(dk * 1000, 1)) for dk, a_ in ans])
    if len(ans) > 1:
        res["reason"] = f"strictest of {len(ans)} border cells: " + res["reason"]
    return res


# 11/11 R5 step 2 (supervisor: "lowered: the 10 cells that reach 0.80 are picked as before, the other 4 unreachable for now; tilt unreachable,
# record only"). The 14 lowered cells' highest straight-down transfer z (m), offline v1 kin, kinematic only:
# outputs/tests/20261111_R5/lowered_ztransfer.json (md5 cfdd6db2f3f3372448547bfa06fdb809), min over 6 directions x 3 classes, 1 mm.
LOWERED_Z = {(471, 303): 0.817, (491, 303): 0.801, (511, 283): 0.818, (531, 283): 0.8, (551, 263): 0.815, (571, 263): 0.795, (591, 243): 0.808,
             (631, 223): 0.798, (651, 203): 0.808, (671, 183): 0.816, (691, 183): 0.792, (711, 163): 0.798, (731, 143): 0.803, (751, 123): 0.806}


def reach_decide(xy, close_yaw_deg, cls, table, transit_z, lowered_z=LOWERED_Z):
    """11/11 R5 step 2 (pure): pick this part with today's straight-down grasp at transit_z?  -> dict(pick, mode, why, cell, ...).
    straight -> pick; lowered -> pick only if the cell's lowered_z >= transit_z (the hand can climb to the lab transit height there);
    tilt -> not yet (step 3, the tilted grasp, is not in lab: recorded as unreachable); unknown -> not picked (never guessed as straight)."""
    r = reach_mode(xy, close_yaw_deg, cls, table)
    out = dict(mode=r["mode"], cell=r.get("cell"), reason=r["reason"], cells=r.get("cells"))
    if r["mode"] == "straight":
        return dict(out, pick=True, why="straight")
    if r["mode"] == "lowered":
        z = lowered_z.get(_key(r["cell"])) if r.get("cell") else None
        if z is not None and z >= float(transit_z) - 1e-9:
            return dict(out, pick=True, why=f"lowered cell, straight down reaches {z:.3f} >= transit {float(transit_z):.3f}", z_max=z)
        return dict(out, pick=False, why=("lowered cell without a computed height" if z is None else
                                          f"lowered cell, straight down only to {z:.3f} < transit {float(transit_z):.3f}"), z_max=z)
    if r["mode"] == "tilt":
        return dict(out, pick=False, why=f"needs a tilted grasp ({r['tilt_deg']} deg {r['tilt_axis']}): not in lab yet (step 3)",
                    tilt_deg=r["tilt_deg"], tilt_axis=r["tilt_axis"], z_transfer=r["z_transfer"])
    return dict(out, pick=False, why="unknown: " + r["reason"], table_says=r.get("table_says"))


