# <</KEEP080>>
FINGER_T, FINGER_W, FINGER_L = 0.031, 0.027, 0.060      # grasp/planner.py FINGER_THICK_M / FINGER_WIDTH_M; finger length = v1 FINGER_LEN (assumed)


def tilt_dirs(yaw):
    """the table yaws nearest to a closing axis (mod 180), two when exactly between"""
    y = float(yaw) % 180.0
    gap = lambda d: abs(((y - d + 90.0) % 180.0) - 90.0)
    g0 = min(gap(d) for d in TILT_YAWS)
    return [d for d in TILT_YAWS if gap(d) <= g0 + 1e-6]


def tilt_lookup(xy, yaw, cls, table, tilt_close=None, keep080=False):
    """11/11 A1 (pure): the smallest tilt about the closing axis (L1) that reaches this grasp (offline table) -> dict(ok, tilt, z_transfer,
    transit_080, why, cells). Border / nearest-cell rule as reach_mode: the strictest of the near cells (any cell without an answer -> not ok).
    An ordinary cell (straight, not in note 81) = tilt 0. Outside the table -> not ok ("unknown"), never guessed.
    keep080 (11/12 seed 290 O2; False = as before): an entry with transit_080 = 0 that KEEP080 answers becomes (that tilt, z_transfer 0.80,
    transit_080 True, keep080 True) -- the tilt kept (plan C) reaches the carry height 0.80; the strictest-cell rule is unchanged."""
    tc = TILT_CLOSE if tilt_close is None else tilt_close
    near = near_cells(xy, table)
    if not near or near[0][0] > MAX_NEAR_M:
        return dict(ok=False, why="unknown: outside the table", tilt=None, cells=[])
    worst = None; cells = []
    for dk, e in near:
        k = _key(e["xy"]); rows = tc.get(k, {}).get(cls) if k in tc else None
        if k in tc:
            if rows is None:
                return dict(ok=False, why=f"unknown: no {cls} entry for cell {e['xy']}", tilt=None, cells=cells)
            for d in tilt_dirs(yaw):
                ent = rows[TILT_YAWS.index(d)]
                cells.append(dict(cell=e["xy"], yaw=d, entry=ent))
                if ent is None:
                    return dict(ok=False, why=f"cell {e['xy']} yaw {d}: no tilt <= 40 about the closing axis reaches it", tilt=None, cells=cells)
                cand = dict(tilt=int(ent[0]), z_transfer=ent[1] / 1000.0, transit_080=bool(ent[2]), cell=e["xy"], yaw=d)
                if keep080 and not ent[2]:                                       # 11/12 O2: the lowered entry -> the kept tilt that reaches 0.80
                    kt_ = (KEEP080.get(k) or {}).get(cls)
                    kt_ = None if kt_ is None else kt_[TILT_YAWS.index(d)]
                    if kt_ is not None:
                        cand = dict(tilt=int(kt_), z_transfer=KEEP080_Z, transit_080=True, cell=e["xy"], yaw=d, keep080=True)
                zc_ = 9.9 if cand["z_transfer"] is None else cand["z_transfer"]; zw_ = 9.9 if worst is None or worst["z_transfer"] is None else worst["z_transfer"]
                if worst is None or abs(cand["tilt"]) > abs(worst["tilt"]) or (abs(cand["tilt"]) == abs(worst["tilt"]) and zc_ < zw_):   # None = no height limit
                    worst = cand
        elif e["how"] == "straight":
            cells.append(dict(cell=e["xy"], yaw=None, entry="straight"))
            if worst is None:
                worst = dict(tilt=0, z_transfer=None, transit_080=True, cell=e["xy"], yaw=None)
        else:
            return dict(ok=False, why=f"unknown: cell {e['xy']} ({e['how']}) not in the tilt table", tilt=None, cells=cells)
    return dict(ok=True, why="table", cells=cells, **worst)


def _v(a, b, s=1.0):
    return [a[0] + s * b[0], a[1] + s * b[1], a[2] + s * b[2]]


def tilt_frame(yaw, tilt):
    """closing axis c (horizontal, yaw), approach a = straight down turned by the signed tilt about c (env_area._tilt_plans about_close),
    across axis m = a x c (horizontal). Pure math."""
    c = [math.cos(math.radians(yaw)), math.sin(math.radians(yaw)), 0.0]; side = [-c[1], c[0], 0.0]     # side = c x down
    t = math.radians(tilt); a = [side[0] * math.sin(t), side[1] * math.sin(t), -math.cos(t)]
    m = [a[1] * c[2] - a[2] * c[1], a[2] * c[0] - a[0] * c[2], a[0] * c[1] - a[1] * c[0]]
    return c, a, m


def lean_sign(xy, yaw, base_xy):
    """+1 / -1: the tilt sign whose hand top (-a) leans toward the arm base (as the offline table)"""
    c = [math.cos(math.radians(yaw)), math.sin(math.radians(yaw))]; side = [-c[1], c[0]]
    return 1 if (-side[0]) * (base_xy[0] - xy[0]) + (-side[1]) * (base_xy[1] - xy[1]) >= 0 else -1


def finger_corners(tcp, yaw, tilt, gap):
    """8 corners of each open finger (tips at the TCP plane, FINGER_L up the hand), world"""
    c, a, m = tilt_frame(yaw, tilt); out = []
    for s in (1, -1):
        cen = _v(tcp, c, s * (gap / 2 + FINGER_T / 2))
        for sx in (-1, 1):
            for sy in (-1, 1):
                for h in (0.0, FINGER_L):
                    p = _v(_v(_v(cen, c, sx * FINGER_T / 2), m, sy * FINGER_W / 2), a, -h)
                    out.append(p)
    return out


def finger_wall_clear(tcp, yaw, tilt, gap, inner, rim_z, z_top, step=0.01):
    """11/11 A1 L3 (pure): the smallest distance (m, < 0 = through the wall) from both open fingers to the source basket's inner walls
    inner = ((x0, y0), (x1, y1)), along the approach line from the grasp up to z_top (pre-grasp / extraction), only corners below rim_z."""
    c, a, m = tilt_frame(yaw, tilt); best = 9.9; s = 0.0
    while True:
        p = _v(tcp, a, -s)
        for q in finger_corners(p, yaw, tilt, gap):
            if q[2] <= rim_z:
                best = min(best, q[0] - inner[0][0], inner[1][0] - q[0], q[1] - inner[0][1], inner[1][1] - q[1])
        if p[2] >= z_top - 1e-9:
            break
        s += step
    return best


def tilt_tip_drop(tilt):
    """how far the lowest fingertip corner goes below the pad centre line when tilted about the closing axis (m)"""
    return FINGER_W / 2 * abs(math.sin(math.radians(tilt)))
